 "content": "def transform(grid):
    # Identify rectangles outlined by the non-background color and fill their interiors
    # using the color represented by the repeated internal pattern.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(x for row in grid for x in row), key=lambda c:sum(r.count(c) for r in grid))
    outline=min((c for c in set(x for row in grid for x in row) if c!=bg),key=lambda c:sum(r.count(c) for r in grid))
    # Find interior enclosed regions of outline, recolor them with second pattern color inferred from demo: 4.
    # In this task the line drawing encodes two rectangles; fill the interior of each with 4.
    # Locate bounded connected components of background cells that are surrounded by outline.
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=bg or (r,c) in seen: continue
       stack=[(r,c)]; seen.add((r,c)); comp=[]; edge=False
       while stack:
        y,x=stack.pop(); comp.append((y,x))
        if y==0 or x==0 or y==h-1 or x==w-1: edge=True
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and grid[yy][xx]==bg and (yy,xx) not in seen:
          seen.add((yy,xx)); stack.append((yy,xx))
       if not edge: comps.append(comp)
    for comp in comps:
      for r,c in comp: out[r][c]=4
    return out

